(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
$$('[data-prism]').forEach(b=>b.addEventListener('click',()=>{$$('[data-prism]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$$('[data-panel]').forEach(x=>x.classList.toggle('active',x.dataset.panel===b.dataset.prism));}));
const plan={gold:['01 / ZŁOTO I SREBRO','Zabierz to, co chcesz wycenić.','Biżuterię, monety lub sztabki. Jeśli masz dokumenty przedmiotu, możesz przynieść je ze sobą. Na miejscu sprawdzimy jego parametry.','złoto lub srebro'],phone:['02 / TELEFON','Pokaż nam swój telefon.','Przygotuj model, informację o stanie i dostępne akcesoria. Przed wizytą warto naładować telefon.','telefon'],other:['03 / INNY PRZEDMIOT','Zacznijmy od krótkiego opisu.','Napisz, co chcesz sprzedać lub zastawić, podaj markę i opisz stan. Ustalimy, czy możemy wycenić przedmiot i co zabrać ze sobą.','przedmiot']};
$$('[data-plan]').forEach(b=>b.addEventListener('click',()=>{const d=plan[b.dataset.plan];$$('[data-plan]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const p=$('#planner-copy');p.querySelector('span').textContent=d[0];p.querySelector('h3').textContent=d[1];p.querySelector('p').textContent=d[2];$('#planner-link').href='https://wa.me/48601775146?text='+encodeURIComponent('Dzień dobry, chcę wycenić '+d[3]+'. Proszę o informację, co przygotować.');}));
const scenes=[['Właściwy moment.','Dobry ruch.','To, co masz, może otworzyć nowe możliwości. Sprawdź skup i pożyczki pod zastaw w SEZAM.','loan','Poznaj możliwości'],['Wartość ukryta','w szczegółach.','Przynieś złoto, srebro, monety lub sztabki. Sprawdzimy przedmiot i przedstawimy wycenę.','gold','Poznaj skup metali'],['Koniec historii?','Nowy rozdział.','Biżuteria i elektronika czekają na kolejnego właściciela. Zapytaj o dostępne przedmioty i obejrzyj je z bliska.','phones','Zobacz możliwości']];
$$('[data-night]').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.night),d=scenes[n];$$('[data-night]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const title=$('#night-title');title.replaceChildren(document.createTextNode(d[0]+' '),document.createElement('br'));const span=document.createElement('span');span.textContent=d[1];title.append(span);$('#night-description').textContent=d[2];$('#night-action').dataset.open=d[3];$('#night-action').firstChild.textContent=d[4]+' ';$('#night-number').textContent='0'+(n+1);}));
if($('#local-clock')){const clock=new Intl.DateTimeFormat('pl-PL',{timeZone:'Europe/Warsaw',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});const update=()=>$('#local-clock').textContent=clock.format(new Date());update();setInterval(update,30000);}
const orbits={gold:['ZŁOTO I SREBRO','Odkryj wartość kruszcu.'],phones:['TELEFONY I LAPTOPY','Daj technologii nowy kierunek.'],jewelry:['BIŻUTERIA','Znajdź swój wyjątkowy detal.'],coins:['MONETY','Zobacz historię w kruszcu.']};
$$('[data-orbit]').forEach(b=>b.addEventListener('click',()=>{const d=orbits[b.dataset.orbit];$$('[data-orbit]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#orbit-topic').textContent=d[0];$('#orbit-detail').textContent=d[1];$('#orbit-open').dataset.open=b.dataset.orbit;}));
$$('[data-studio]').forEach(b=>b.addEventListener('click',()=>{$$('[data-studio]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$$('[data-studio-card]').forEach(x=>x.hidden=b.dataset.studio!=='all'&&x.dataset.studioCard!==b.dataset.studio);}));
})();
